32	const getSavedChatTags = async (
33	  context: CommandContext,
34	  mtSortDesc: boolean,
35	): Promise<ChatDetail[]> => {
36	  const cfg = context.services.config;
37	  const geminiDir = cfg?.storage?.getProjectTempDir();
38	  if (!geminiDir) {
39	    return [];
40	  }
41	  try {
42	    const file_head = 'checkpoint-';
43	    const file_tail = '.json';
44	    const files = await fsPromises.readdir(geminiDir);
45	    const chatDetails: ChatDetail[] = [];
46	
47	    for (const file of files) {
48	      if (file.startsWith(file_head) && file.endsWith(file_tail)) {
49	        const filePath = path.join(geminiDir, file);
50	        const stats = await fsPromises.stat(filePath);
51	        const tagName = file.slice(file_head.length, -file_tail.length);
52	        chatDetails.push({
53	          name: decodeTagName(tagName),
54	          mtime: stats.mtime.toISOString(),
55	        });
56	      }
57	    }
58	
59	    chatDetails.sort((a, b) =>
60	      mtSortDesc
61	        ? b.mtime.localeCompare(a.mtime)
62	        : a.mtime.localeCompare(b.mtime),
63	    );
64	
65	    return chatDetails;
66	  } catch (_err) {
67	    return [];
68	  }
69	};
