88	const saveCommand: SlashCommand = {
89	  name: 'save',
90	  description:
91	    'Save the current conversation as a checkpoint. Usage: /chat save <tag>',
92	  kind: CommandKind.BUILT_IN,
93	  autoExecute: false,
94	  action: async (context, args): Promise<SlashCommandActionReturn | void> => {
95	    const tag = args.trim();
96	    if (!tag) {
97	      return {
98	        type: 'message',
99	        messageType: 'error',
