101	      };
102	    }
103	
104	    const { logger, config } = context.services;
105	    await logger.initialize();
106	
107	    if (!context.overwriteConfirmed) {
108	      const exists = await logger.checkpointExists(tag);
109	      if (exists) {
110	        return {
111	          type: 'confirm_action',
112	          prompt: React.createElement(
113	            Text,
114	            null,
115	            'A checkpoint with the tag ',
116	            React.createElement(Text, { color: theme.text.accent }, tag),
117	            ' already exists. Do you want to overwrite it?',
118	          ),
119	          originalInvocation: {
120	            raw: context.invocation?.raw || `/chat save ${tag}`,
121	          },
122	        };
123	      }
124	    }
125	
126	    const chat = config?.getGeminiClient()?.getChat();
127	    if (!chat) {
128	      return {
129	        type: 'message',
130	        messageType: 'error',
131	        content: 'No chat client available to save conversation.',
132	      };
133	    }
134	
135	    const history = chat.getHistory();
136	    if (history.length > INITIAL_HISTORY_LENGTH) {
137	      const authType = config?.getContentGeneratorConfig()?.authType;
138	      await logger.saveCheckpoint({ history, authType }, tag);
139	      return {
140	        type: 'message',
141	        messageType: 'info',
142	        content: `Conversation checkpoint saved with tag: ${decodeTagName(
143	          tag,
144	        )}.`,
145	      };
146	    } else {
147	      return {
148	        type: 'message',
149	        messageType: 'info',
150	        content: 'No conversation found to save.',
151	      };
152	    }
153	  },
154	};
