7	import { Box, Text } from 'ink';
8	import { theme } from '../semantic-colors.js';
9	import { ExpandableText, MAX_WIDTH } from './shared/ExpandableText.js';
10	import { CommandKind } from '../commands/types.js';
11	import { Colors } from '../colors.js';
12	import { sanitizeForDisplay } from '../utils/textUtils.js';
13	
14	export interface Suggestion {
15	  label: string;
16	  value: string;
17	  description?: string;
18	  matchedIndex?: number;
19	  commandKind?: CommandKind;
20	}
21	interface SuggestionsDisplayProps {
22	  suggestions: Suggestion[];
23	  activeIndex: number;
24	  isLoading: boolean;
25	  width: number;
26	  scrollOffset: number;
27	  userInput: string;
28	  mode: 'reverse' | 'slash';
29	  expandedIndex?: number;
30	}
31	
32	export const MAX_SUGGESTIONS_TO_SHOW = 8;
33	export { MAX_WIDTH };
34	
35	export function SuggestionsDisplay({
36	  suggestions,
37	  activeIndex,
38	  isLoading,
39	  width,
40	  scrollOffset,
41	  userInput,
42	  mode,
43	  expandedIndex,
44	}: SuggestionsDisplayProps) {
45	  if (isLoading) {
46	    return (
47	      <Box paddingX={1} width={width}>
48	        <Text color="gray">Loading suggestions...</Text>
49	      </Box>
50	    );
51	  }
52	
53	  if (suggestions.length === 0) {
54	    return null; // Don't render anything if there are no suggestions
55	  }
56	
57	  // Calculate the visible slice based on scrollOffset
58	  const startIndex = scrollOffset;
59	  const endIndex = Math.min(
60	    scrollOffset + MAX_SUGGESTIONS_TO_SHOW,
61	    suggestions.length,
62	  );
63	  const visibleSuggestions = suggestions.slice(startIndex, endIndex);
64	
65	  const COMMAND_KIND_SUFFIX: Partial<Record<CommandKind, string>> = {
66	    [CommandKind.MCP_PROMPT]: ' [MCP]',
67	    [CommandKind.AGENT]: ' [Agent]',
68	  };
69	
70	  const getFullLabel = (s: Suggestion) =>
71	    s.label + (s.commandKind ? (COMMAND_KIND_SUFFIX[s.commandKind] ?? '') : '');
72	
73	  const maxLabelLength = Math.max(
74	    ...suggestions.map((s) => getFullLabel(s).length),
75	  );
76	  const commandColumnWidth =
77	    mode === 'slash' ? Math.min(maxLabelLength, Math.floor(width * 0.5)) : 0;
78	
79	  return (
80	    <Box flexDirection="column" paddingX={1} width={width}>
81	      {scrollOffset > 0 && <Text color={theme.text.primary}>▲</Text>}
82	
83	      {visibleSuggestions.map((suggestion, index) => {
84	        const originalIndex = startIndex + index;
85	        const isActive = originalIndex === activeIndex;
86	        const isExpanded = originalIndex === expandedIndex;
87	        const textColor = isActive ? theme.ui.focus : theme.text.secondary;
88	        const isLong = suggestion.value.length >= MAX_WIDTH;
89	        const labelElement = (
90	          <ExpandableText
91	            label={suggestion.value}
92	            matchedIndex={suggestion.matchedIndex}
93	            userInput={userInput}
94	            textColor={textColor}
95	            isExpanded={isExpanded}
96	          />
97	        );
98	
99	        return (
100	          <Box
101	            key={`${suggestion.value}-${originalIndex}`}
102	            flexDirection="row"
103	            backgroundColor={isActive ? theme.background.focus : undefined}
104	          >
105	            <Box
106	              {...(mode === 'slash'
107	                ? { width: commandColumnWidth, flexShrink: 0 as const }
108	                : { flexShrink: 1 as const })}
109	            >
110	              <Box>
111	                {labelElement}
112	                {suggestion.commandKind &&
113	                  COMMAND_KIND_SUFFIX[suggestion.commandKind] && (
114	                    <Text color={textColor}>
115	                      {COMMAND_KIND_SUFFIX[suggestion.commandKind]}
116	                    </Text>
117	                  )}
118	              </Box>
119	            </Box>
120	
121	            {suggestion.description && (
122	              <Box flexGrow={1} paddingLeft={3}>
123	                <Text color={textColor} wrap="truncate">
124	                  {sanitizeForDisplay(suggestion.description, 100)}
125	                </Text>
126	              </Box>
127	            )}
128	            {isActive && isLong && (
129	              <Box width={3} flexShrink={0}>
130	                <Text color={Colors.Gray}>{isExpanded ? ' ← ' : ' → '}</Text>
131	              </Box>
132	            )}
133	          </Box>
134	        );
135	      })}
136	      {endIndex < suggestions.length && <Text color="gray">▼</Text>}
137	      {suggestions.length > MAX_SUGGESTIONS_TO_SHOW && (
138	        <Text color="gray">
139	          ({activeIndex + 1}/{suggestions.length})
140	        </Text>
141	      )}
142	    </Box>
143	  );
144	}
