42	// Shared utility function for command matching logic
43	function matchesCommand(cmd: SlashCommand, query: string): boolean {
44	  return (
45	    cmd.name.toLowerCase() === query.toLowerCase() ||
46	    cmd.altNames?.some((alt) => alt.toLowerCase() === query.toLowerCase()) ||
47	    false
48	  );
