51	interface CommandParserResult {
52	  hasTrailingSpace: boolean;
53	  commandPathParts: string[];
54	  partial: string;
55	  currentLevel: readonly SlashCommand[] | undefined;
56	  leafCommand: SlashCommand | null;
57	  exactMatchAsParent: SlashCommand | undefined;
58	  isArgumentCompletion: boolean;
