61	function useCommandParser(
62	  query: string | null,
63	  slashCommands: readonly SlashCommand[],
64	): CommandParserResult {
65	  return useMemo(() => {
66	    if (!query) {
67	      return {
68	        hasTrailingSpace: false,
69	        commandPathParts: [],
70	        partial: '',
71	        currentLevel: slashCommands,
72	        leafCommand: null,
73	        exactMatchAsParent: undefined,
74	        isArgumentCompletion: false,
75	      };
76	    }
77	
78	    const fullPath = query.substring(1) || '';
79	    const hasTrailingSpace = !!query.endsWith(' ');
80	    const rawParts = fullPath.split(/\s+/).filter((p) => p);
81	    let commandPathParts = rawParts;
82	    let partial = '';
83	
84	    if (!hasTrailingSpace && rawParts.length > 0) {
85	      partial = rawParts[rawParts.length - 1];
86	      commandPathParts = rawParts.slice(0, -1);
87	    }
88	
89	    let currentLevel: readonly SlashCommand[] | undefined = slashCommands;
90	    let leafCommand: SlashCommand | null = null;
91	
92	    for (const part of commandPathParts) {
93	      if (!currentLevel) {
94	        leafCommand = null;
95	        currentLevel = [];
96	        break;
97	      }
98	      const found: SlashCommand | undefined = currentLevel.find((cmd) =>
99	        matchesCommand(cmd, part),
100	      );
101	
102	      if (found) {
103	        leafCommand = found;
104	        currentLevel = found.subCommands as readonly SlashCommand[] | undefined;
105	        if (found.kind === CommandKind.MCP_PROMPT) {
106	          break;
107	        }
108	      } else {
109	        leafCommand = null;
110	        currentLevel = [];
111	        break;
112	      }
113	    }
114	
115	    let exactMatchAsParent: SlashCommand | undefined;
116	    if (!hasTrailingSpace && currentLevel) {
117	      exactMatchAsParent = currentLevel.find(
118	        (cmd) => matchesCommand(cmd, partial) && cmd.subCommands,
119	      );
120	
121	      if (exactMatchAsParent) {
122	        // Only descend if there are NO other matches for the partial at this level.
123	        // This ensures that typing "/memory" still shows "/memory-leak" if it exists.
124	        const otherMatches = currentLevel.filter(
125	          (cmd) =>
126	            cmd !== exactMatchAsParent &&
127	            (cmd.name.toLowerCase().startsWith(partial.toLowerCase()) ||
128	              cmd.altNames?.some((alt) =>
129	                alt.toLowerCase().startsWith(partial.toLowerCase()),
130	              )),
131	        );
132	
133	        if (otherMatches.length === 0) {
134	          leafCommand = exactMatchAsParent;
135	          currentLevel = exactMatchAsParent.subCommands as
136	            | readonly SlashCommand[]
137	            | undefined;
138	          partial = '';
139	        }
140	      }
141	    }
142	
143	    const depth = commandPathParts.length;
144	    const isArgumentCompletion = !!(
145	      leafCommand?.completion &&
146	      (hasTrailingSpace ||
147	        (rawParts.length > depth && depth > 0 && partial !== ''))
148	    );
