150	    return {
151	      hasTrailingSpace,
152	      commandPathParts,
153	      partial,
154	      currentLevel,
155	      leafCommand,
156	      exactMatchAsParent,
157	      isArgumentCompletion,
158	    };
159	  }, [query, slashCommands]);
160	}
