34	// Centralized fuzzy matching simulation logic
35	// Note: This is a simplified reimplementation that may diverge from real fzf behavior.
36	// Integration tests in useSlashCompletion.integration.test.ts use the real fzf library
37	// to catch any behavioral differences and serve as our "canary in a coal mine."
38	function simulateFuzzyMatching(items: readonly string[], query: string) {
39	  const results = [];
40	  if (query) {
41	    const lowerQuery = query.toLowerCase();
42	    for (const item of items) {
43	      const lowerItem = item.toLowerCase();
44	
45	      // Exact match gets highest score
46	      if (lowerItem === lowerQuery) {
47	        results.push({
48	          item,
49	          positions: [],
50	          score: 100,
51	          start: 0,
52	          end: item.length,
53	        });
54	        continue;
55	      }
56	
57	      // Prefix match gets high score
58	      if (lowerItem.startsWith(lowerQuery)) {
59	        results.push({
60	          item,
61	          positions: [],
62	          score: 80,
63	          start: 0,
64	          end: query.length,
65	        });
66	        continue;
67	      }
68	
69	      // Fuzzy matching: check if query chars appear in order
70	      let queryIndex = 0;
71	      let score = 0;
72	      for (
73	        let i = 0;
74	        i < lowerItem.length && queryIndex < lowerQuery.length;
75	        i++
76	      ) {
77	        if (lowerItem[i] === lowerQuery[queryIndex]) {
78	          queryIndex++;
79	          score += 10 - i; // Earlier matches get higher scores
80	        }
81	      }
82	
83	      // If all query characters were found in order, include this item
84	      if (queryIndex === lowerQuery.length) {
85	        results.push({
86	          item,
87	          positions: [],
88	          score,
89	          start: 0,
90	          end: query.length,
91	        });
92	      }
93	    }
94	  }
95	
96	  // Sort by score descending (better matches first)
97	  results.sort((a, b) => b.score - a.score);
98	  return Promise.resolve(results);
99	}
